// Cafe menu from coffeebean.pk: Beverage + Food, plus the "Cake To Go" cakes.
// Source data is generated by scripts/scrape_coffeebean.py into ./cbtl/.
// The old site publishes no prices, so price is null until real prices are added.
import { menuItems as cafeMenu } from "./cbtl/menu"
import { products } from "./cbtl/products"

const cakes = products
  .filter((p) => p.category === "Cake")
  .map((p) => ({ name: p.name, desc: p.desc, price: p.price, img: p.img, category: "Cakes" }))

// Items also listed under a second tab. The old site has only two
// "Non-Coffee Favorites", so their iced counterparts from "Non-Coffee" join them.
const alsoIn = {
  "Pure Vanilla Ice Blended Drink": ["Non-Coffee Favorites"],
  "Pure Double Chocolate Ice Blended Drink": ["Non-Coffee Favorites"],
}

export const menuItems = [
  ...cafeMenu.map(({ name, desc, price, img, category }) => ({
    name,
    desc,
    price,
    img,
    category,
    alsoIn: alsoIn[name] ?? [],
  })),
  ...cakes.map((item) => ({ ...item, alsoIn: [] })),
]

export const inCategory = (item, category) =>
  item.category === category || item.alsoIn.includes(category)

export const categories = [...new Set(menuItems.map((item) => item.category))]

// Prices are in PKR, as on coffeebean.pk. Missing prices render as nothing.
export const money = (n) => (n == null ? "" : `Rs ${Math.round(n).toLocaleString("en-PK")}`)
